// TagManager.js - Tag management functionalities
import { createElement } from '../utils/dom.js';

// State
let activeTags = [];
let allTags = new Set();

/**
 * Initialize the Tag Manager component
 * Sets up event listeners and UI
 */
export function initTagManager() {
  // Set up event listeners
  setupEventListeners();
  
  // Initialize tag list UI
  renderTagList();
}

/**
 * Sets up event listeners for the Tag Manager
 */
function setupEventListeners() {
  // Listen for posts loaded event to extract tags
  window.addEventListener('posts:loaded', (event) => {
    if (event.detail && event.detail.posts) {
      extractTagsFromPosts(event.detail.posts);
      renderTagList();
    }
  });
  
  // Listen for local posts loaded
  window.addEventListener('posts:load-local', async (event) => {
    if (event.detail && event.detail.posts) {
      extractTagsFromPosts(event.detail.posts);
      renderTagList();
    }
  });
  
  // Listen for post added event
  window.addEventListener('post:added', (event) => {
    if (event.detail && event.detail.post && event.detail.post.tags) {
      // Add new tags to the set
      event.detail.post.tags.forEach(tag => allTags.add(tag));
      renderTagList();
    }
  });
  
  // Listen for post updated event
  window.addEventListener('post:updated', (event) => {
    if (event.detail && event.detail.updates && event.detail.updates.tags) {
      // We need to re-extract all tags since we don't know which ones were removed
      window.dispatchEvent(new CustomEvent('tags:refresh-needed'));
    }
  });
  
  // Listen for tag filter updated event
  window.addEventListener('filter:tag:updated', (event) => {
    if (event.detail && event.detail.tags) {
      activeTags = event.detail.tags;
      renderTagList();
    }
  });
  
  // Listen for tags refresh needed event
  window.addEventListener('tags:refresh-needed', async () => {
    // This would typically fetch all posts again to extract tags
    // For now, we'll just re-render with the current tags
    renderTagList();
  });
}

/**
 * Extracts unique tags from a list of posts
 * @param {Array} posts - List of posts to extract tags from
 */
function extractTagsFromPosts(posts) {
  // Clear existing tags
  allTags.clear();
  
  // Extract tags from posts
  posts.forEach(post => {
    if (post.tags && Array.isArray(post.tags)) {
      post.tags.forEach(tag => allTags.add(tag));
    }
  });
}

/**
 * Renders the tag list in the UI
 */
function renderTagList() {
  const tagListContainer = document.getElementById('tag-list');
  if (!tagListContainer) return;
  
  // Clear existing tags
  tagListContainer.innerHTML = '';
  
  // If no tags, show empty state
  if (allTags.size === 0) {
    const emptyState = document.createElement('span');
    emptyState.className = 'text-gray-500 text-sm';
    emptyState.textContent = 'No tags yet';
    tagListContainer.appendChild(emptyState);
    return;
  }
  
  // Sort tags alphabetically
  const sortedTags = Array.from(allTags).sort();
  
  // Create tag elements
  sortedTags.forEach(tag => {
    const isActive = activeTags.includes(tag);
    const tagElement = createTagElement(tag, isActive);
    tagListContainer.appendChild(tagElement);
  });
  
  // Add clear filters button if there are active tags
  if (activeTags.length > 0) {
    const clearButton = createElement('button', {
      className: 'text-xs text-primary-600 hover:text-primary-800 ml-2',
      onclick: () => {
        // Clear active tags
        activeTags = [];
        
        // Dispatch event to update filters
        window.dispatchEvent(new CustomEvent('filter:tag:updated', {
          detail: { tags: activeTags }
        }));
        
        // Dispatch event to update grid
        window.dispatchEvent(new CustomEvent('filter:tag', {
          detail: { tag: null, active: false, clearAll: true }
        }));
      }
    }, 'Clear Filters');
    
    tagListContainer.appendChild(clearButton);
  }
}

/**
 * Creates a tag element
 * @param {string} tag - Tag text
 * @param {boolean} isActive - Whether the tag is active
 * @returns {HTMLElement} The tag element
 */
function createTagElement(tag, isActive) {
  const tagElement = createElement('span', {
    className: `tag cursor-pointer ${isActive ? 'bg-primary-600 text-white' : ''}`,
    onclick: () => handleTagClick(tag)
  }, tag);
  
  return tagElement;
}

/**
 * Handles tag click event
 * @param {string} tag - The clicked tag
 */
function handleTagClick(tag) {
  // Toggle tag in active tags
  const isActive = activeTags.includes(tag);
  
  if (isActive) {
    // Remove tag from active tags
    activeTags = activeTags.filter(t => t !== tag);
  } else {
    // Add tag to active tags
    activeTags = [...activeTags, tag];
  }
  
  // Dispatch event to update filters
  window.dispatchEvent(new CustomEvent('filter:tag', {
    detail: { tag, active: !isActive }
  }));
  
  // Render tag list with updated active tags
  renderTagList();
}

/**
 * Gets all available tags
 * @returns {Array} Array of all tags
 */
export function getAllTags() {
  return Array.from(allTags);
}

/**
 * Gets active tags
 * @returns {Array} Array of active tags
 */
export function getActiveTags() {
  return activeTags;
}
