// AddLink.js - Component for adding new links
import { createPost, getPlatformFromUrl, fetchUrlMetadata, generateEmbedHtml } from '../utils/api.js';
import { showToast } from '../utils/dom.js';
import { currentUser } from '../simple-auth.js';

/**
 * Initialize the Add Link component
 * Sets up event listeners and form handling
 */
export function initAddLink() {
  // Create and inject the form into the container
  createAddLinkForm();
  
  // Set up event listeners
  setupEventListeners();
}

/**
 * Creates the Add Link form and injects it into the container
 */
function createAddLinkForm() {
  const container = document.getElementById('add-link-form-container');
  if (!container) return;
  
  const formHTML = `
    <form id="add-link-form" class="space-y-4">
      <div>
        <label for="link-url" class="form-label">URL</label>
        <input type="url" id="link-url" class="form-input" placeholder="https://example.com/post" required>
      </div>
      
      <div>
        <label for="link-title" class="form-label">Title (Optional)</label>
        <input type="text" id="link-title" class="form-input" placeholder="Post title">
      </div>
      
      <div>
        <label for="link-description" class="form-label">Description (Optional)</label>
        <textarea id="link-description" class="form-input" rows="2" placeholder="Brief description"></textarea>
      </div>
      
      <div>
        <label for="link-tags" class="form-label">Tags (comma separated)</label>
        <input type="text" id="link-tags" class="form-input" placeholder="tag1, tag2, tag3">
      </div>
      
      <div class="flex justify-end space-x-2">
        <button type="button" id="cancel-add-link" class="btn btn-secondary">Cancel</button>
        <button type="submit" class="btn btn-primary">Add Link</button>
      </div>
    </form>
  `;
  
  container.innerHTML = formHTML;
}

/**
 * Sets up event listeners for the Add Link form
 */
function setupEventListeners() {
  const form = document.getElementById('add-link-form');
  const cancelButton = document.getElementById('cancel-add-link');
  const urlInput = document.getElementById('link-url');
  
  if (form) {
    form.addEventListener('submit', handleFormSubmit);
  }
  
  if (cancelButton) {
    cancelButton.addEventListener('click', () => {
      // Hide the form
      const container = document.getElementById('add-link-form-container');
      if (container) {
        container.classList.add('hidden');
      }
      
      // Reset the form
      if (form) {
        form.reset();
      }
    });
  }
  
  // Auto-detect metadata when URL is entered
  if (urlInput) {
    urlInput.addEventListener('blur', async () => {
      const url = urlInput.value.trim();
      if (url && isValidUrl(url)) {
        try {
          // Show loading state
          urlInput.classList.add('bg-gray-100');
          
          // Fetch metadata for the URL
          const metadata = await fetchUrlMetadata(url);
          
          // Fill in form fields if they're empty
          const titleInput = document.getElementById('link-title');
          const descriptionInput = document.getElementById('link-description');
          
          if (titleInput && !titleInput.value && metadata.title) {
            titleInput.value = metadata.title;
          }
          
          if (descriptionInput && !descriptionInput.value && metadata.description) {
            descriptionInput.value = metadata.description;
          }
        } catch (error) {
          console.error('Error fetching URL metadata:', error);
        } finally {
          // Remove loading state
          urlInput.classList.remove('bg-gray-100');
        }
      }
    });
  }
}

/**
 * Handles form submission
 * @param {Event} event - Form submit event
 */
async function handleFormSubmit(event) {
  event.preventDefault();
  
  const form = event.target;
  const urlInput = form.querySelector('#link-url');
  const titleInput = form.querySelector('#link-title');
  const descriptionInput = form.querySelector('#link-description');
  const tagsInput = form.querySelector('#link-tags');
  
  const url = urlInput.value.trim();
  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();
  const tagsString = tagsInput.value.trim();
  
  // Validate URL
  if (!url || !isValidUrl(url)) {
    showToast('Please enter a valid URL', 'error');
    urlInput.focus();
    return;
  }
  
  // Parse tags
  const tags = tagsString
    ? tagsString.split(',').map(tag => tag.trim()).filter(tag => tag)
    : [];
  
  try {
    // Show loading state
    const submitButton = form.querySelector('button[type="submit"]');
    if (submitButton) {
      submitButton.disabled = true;
      submitButton.textContent = 'Adding...';
    }
    
    // Determine platform from URL
    const platform = getPlatformFromUrl(url);
    
    // Generate embed HTML
    const embedHtml = await generateEmbedHtml(url, platform);
    
    // Get current user ID from our auth system
    const userId = currentUser ? currentUser.id : null;
    console.log('AddLink: User ID:', userId);
    
    // Create post object
    const post = {
      url,
      title: title || url,
      description,
      platform,
      embed_html: embedHtml,
      tags,
      position: 0, // Will be adjusted when added to the grid
      userId // For local storage
    };
    
    // Save post
    await createPost(post, userId);
    
    // Reset form
    form.reset();
    
    // Hide form container
    const container = document.getElementById('add-link-form-container');
    if (container) {
      container.classList.add('hidden');
    }
    
    // Show appropriate success message
    if (userId) {
      showToast('Link added successfully', 'success');
    } else {
      showToast('Link added to local storage. Sign in to sync with your account.', 'info', 5000);
    }
    
    // Dispatch event to notify other components
    window.dispatchEvent(new CustomEvent('post:added', { detail: { post } }));
  } catch (error) {
    console.error('Error adding link:', error);
    showToast('Error adding link. Please try again.', 'error');
  } finally {
    // Reset button state
    const submitButton = form.querySelector('button[type="submit"]');
    if (submitButton) {
      submitButton.disabled = false;
      submitButton.textContent = 'Add Link';
    }
  }
}

/**
 * Validates a URL
 * @param {string} url - URL to validate
 * @returns {boolean} Whether the URL is valid
 */
function isValidUrl(url) {
  try {
    new URL(url);
    return true;
  } catch (error) {
    return false;
  }
}
