// dom.js - Helper functions for DOM manipulation

/**
 * Creates an element with attributes and content
 * @param {string} tag - HTML tag name
 * @param {Object} attributes - Element attributes
 * @param {string|Node|Array} content - Element content (string, DOM node, or array of nodes)
 * @returns {HTMLElement} The created element
 */
export function createElement(tag, attributes = {}, content = null) {
  const element = document.createElement(tag);
  
  // Set attributes
  Object.entries(attributes).forEach(([key, value]) => {
    if (key === 'className') {
      element.className = value;
    } else if (key === 'dataset') {
      Object.entries(value).forEach(([dataKey, dataValue]) => {
        element.dataset[dataKey] = dataValue;
      });
    } else if (key === 'style' && typeof value === 'object') {
      Object.entries(value).forEach(([styleKey, styleValue]) => {
        element.style[styleKey] = styleValue;
      });
    } else if (key.startsWith('on') && typeof value === 'function') {
      const eventName = key.substring(2).toLowerCase();
      element.addEventListener(eventName, value);
    } else {
      element.setAttribute(key, value);
    }
  });
  
  // Set content
  if (content !== null) {
    appendContent(element, content);
  }
  
  return element;
}

/**
 * Appends content to an element
 * @param {HTMLElement} element - The parent element
 * @param {string|Node|Array} content - Content to append
 */
export function appendContent(element, content) {
  if (typeof content === 'string') {
    element.textContent = content;
  } else if (content instanceof Node) {
    element.appendChild(content);
  } else if (Array.isArray(content)) {
    content.forEach(item => {
      if (item) {
        appendContent(element, item);
      }
    });
  }
}

/**
 * Creates a button element
 * @param {string} text - Button text
 * @param {Function} onClick - Click handler
 * @param {string} className - CSS class
 * @returns {HTMLButtonElement} The button element
 */
export function createButton(text, onClick, className = '') {
  return createElement('button', {
    className,
    onclick: onClick
  }, text);
}

/**
 * Debounce a function call
 * @param {Function} func - Function to debounce
 * @param {number} wait - Wait time in milliseconds
 * @returns {Function} Debounced function
 */
export function debounce(func, wait = 300) {
  let timeout;
  
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

/**
 * Throttle a function call
 * @param {Function} func - Function to throttle
 * @param {number} limit - Limit in milliseconds
 * @returns {Function} Throttled function
 */
export function throttle(func, limit = 300) {
  let inThrottle;
  
  return function executedFunction(...args) {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => {
        inThrottle = false;
      }, limit);
    }
  };
}

/**
 * Creates a loading spinner element
 * @returns {HTMLElement} The loading spinner element
 */
export function createLoadingSpinner() {
  return createElement('div', {
    className: 'loading-spinner'
  });
}

/**
 * Creates a message toast that disappears after a delay
 * @param {string} message - Message to display
 * @param {string} type - Message type (success, error, info)
 * @param {number} duration - Duration in milliseconds
 */
export function showToast(message, type = 'info', duration = 3000) {
  // Remove any existing toasts
  const existingToast = document.querySelector('.toast');
  if (existingToast) {
    existingToast.remove();
  }
  
  // Create toast element
  const toast = createElement('div', {
    className: `toast toast-${type}`,
    style: {
      position: 'fixed',
      bottom: '20px',
      right: '20px',
      zIndex: '1000',
      padding: '12px 20px',
      borderRadius: '4px',
      backgroundColor: type === 'error' ? '#f44336' : type === 'success' ? '#4caf50' : '#2196f3',
      color: 'white',
      boxShadow: '0 4px 8px rgba(0,0,0,0.1)',
      transition: 'opacity 0.3s ease-in-out',
      opacity: '0'
    }
  }, message);
  
  // Add to document
  document.body.appendChild(toast);
  
  // Trigger animation
  setTimeout(() => {
    toast.style.opacity = '1';
  }, 10);
  
  // Remove after duration
  setTimeout(() => {
    toast.style.opacity = '0';
    setTimeout(() => {
      toast.remove();
    }, 300);
  }, duration);
}

/**
 * Creates a confirmation dialog
 * @param {string} message - Dialog message
 * @param {Function} onConfirm - Confirm callback
 * @param {Function} onCancel - Cancel callback
 */
export function showConfirm(message, onConfirm, onCancel = null) {
  // Create backdrop
  const backdrop = createElement('div', {
    className: 'modal-backdrop',
    style: {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      backgroundColor: 'rgba(0,0,0,0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: '1000'
    }
  });
  
  // Create dialog
  const dialog = createElement('div', {
    className: 'confirm-dialog',
    style: {
      backgroundColor: 'white',
      padding: '20px',
      borderRadius: '8px',
      maxWidth: '400px',
      width: '100%',
      boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
    }
  });
  
  // Add message
  const messageEl = createElement('p', {
    style: {
      marginTop: '0',
      marginBottom: '20px'
    }
  }, message);
  
  // Add buttons
  const buttonContainer = createElement('div', {
    style: {
      display: 'flex',
      justifyContent: 'flex-end',
      gap: '10px'
    }
  });
  
  const cancelButton = createButton('Cancel', () => {
    document.body.removeChild(backdrop);
    if (onCancel) onCancel();
  }, 'btn btn-secondary');
  
  const confirmButton = createButton('Confirm', () => {
    document.body.removeChild(backdrop);
    onConfirm();
  }, 'btn btn-primary');
  
  buttonContainer.appendChild(cancelButton);
  buttonContainer.appendChild(confirmButton);
  
  dialog.appendChild(messageEl);
  dialog.appendChild(buttonContainer);
  backdrop.appendChild(dialog);
  
  document.body.appendChild(backdrop);
}

/**
 * Adds infinite scroll functionality to an element
 * @param {HTMLElement} container - The scrollable container
 * @param {Function} loadMore - Function to load more content
 * @param {number} threshold - Pixel threshold before bottom to trigger load
 */
export function setupInfiniteScroll(container, loadMore, threshold = 200) {
  const scrollHandler = throttle(() => {
    const { scrollTop, scrollHeight, clientHeight } = container;
    
    if (scrollHeight - scrollTop - clientHeight < threshold) {
      loadMore();
    }
  }, 200);
  
  container.addEventListener('scroll', scrollHandler);
  
  // Return a function to remove the scroll listener
  return () => {
    container.removeEventListener('scroll', scrollHandler);
  };
}

/**
 * Formats a date string to a more readable format
 * @param {string} dateString - ISO date string
 * @returns {string} Formatted date string
 */
export function formatDate(dateString) {
  if (!dateString) return '';
  
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now - date;
  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);
  
  if (diffDays > 30) {
    return date.toLocaleDateString();
  } else if (diffDays > 0) {
    return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
  } else if (diffHours > 0) {
    return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  } else if (diffMins > 0) {
    return `${diffMins} minute${diffMins > 1 ? 's' : ''} ago`;
  } else {
    return 'Just now';
  }
}
