// PostGrid.js - Component for displaying posts in a masonry grid
import { createPostCard } from './PostCard.js';
import { getPosts } from '../utils/storage.js';
import { setupInfiniteScroll } from '../utils/dom.js';

// Constants
const POSTS_PER_PAGE = 12;

// State
let currentPosts = [];
let currentPage = 1;
let activeFilters = {
  tags: [],
  platform: null,
  search: ''
};
let isLoading = false;
let hasMorePosts = true;
let infiniteScrollCleanup = null;

/**
 * Initialize the Post Grid component
 * Sets up event listeners and initial rendering
 */
export function initPostGrid() {
  // Set up event listeners
  setupEventListeners();
  
  // Set up infinite scroll
  setupInfiniteScrolling();
}

/**
 * Sets up event listeners for the Post Grid
 */
function setupEventListeners() {
  // Listen for post added event
  window.addEventListener('post:added', (event) => {
    if (event.detail && event.detail.post) {
      // Add the new post to the current posts
      currentPosts = [event.detail.post, ...currentPosts];
      
      // Render the grid with the updated posts
      renderGrid();
    }
  });
  
  // Listen for post updated event
  window.addEventListener('post:updated', (event) => {
    if (event.detail && event.detail.postId) {
      const { postId, updates } = event.detail;
      
      // Update the post in the current posts array
      currentPosts = currentPosts.map(post => {
        if (post.id === postId) {
          return { ...post, ...updates };
        }
        return post;
      });
      
      // Render the grid with the updated posts
      renderGrid();
    }
  });
  
  // Listen for posts loaded event
  window.addEventListener('posts:loaded', (event) => {
    if (event.detail && event.detail.posts) {
      // Reset state
      currentPosts = event.detail.posts;
      currentPage = 1;
      hasMorePosts = true;
      
      // Render the grid with the loaded posts
      renderGrid();
    }
  });
  
  // Listen for load local posts event
  window.addEventListener('posts:load-local', async () => {
    // Load posts from local storage
    const posts = await getPosts();
    
    // Update state
    currentPosts = posts;
    currentPage = 1;
    hasMorePosts = true;
    
    // Render the grid
    renderGrid();
  });
  
  // Listen for tag filter event
  window.addEventListener('filter:tag', (event) => {
    if (event.detail && event.detail.tag) {
      const { tag, active } = event.detail;
      
      if (active) {
        // Add tag to filters if not already present
        if (!activeFilters.tags.includes(tag)) {
          activeFilters.tags = [...activeFilters.tags, tag];
        }
      } else {
        // Remove tag from filters
        activeFilters.tags = activeFilters.tags.filter(t => t !== tag);
      }
      
      // Reset pagination
      currentPage = 1;
      hasMorePosts = true;
      
      // Render the grid with the updated filters
      renderGrid();
    }
  });
  
  // Listen for platform filter event
  window.addEventListener('filter:platform', (event) => {
    if (event.detail) {
      activeFilters.platform = event.detail.platform || null;
      
      // Reset pagination
      currentPage = 1;
      hasMorePosts = true;
      
      // Render the grid with the updated filters
      renderGrid();
    }
  });
  
  // Listen for search filter event
  window.addEventListener('filter:search', (event) => {
    if (event.detail) {
      activeFilters.search = event.detail.query || '';
      
      // Reset pagination
      currentPage = 1;
      hasMorePosts = true;
      
      // Render the grid with the updated filters
      renderGrid();
    }
  });
}

/**
 * Sets up infinite scrolling for the post grid
 */
function setupInfiniteScrolling() {
  // Clean up existing scroll handler if any
  if (infiniteScrollCleanup) {
    infiniteScrollCleanup();
  }
  
  // Set up new scroll handler
  infiniteScrollCleanup = setupInfiniteScroll(window, loadMorePosts, 200);
}

/**
 * Loads more posts for infinite scrolling
 */
async function loadMorePosts() {
  if (isLoading || !hasMorePosts) return;
  
  isLoading = true;
  showLoadingIndicator();
  
  try {
    // In a real app, this would fetch more posts from the API
    // For now, we'll just simulate pagination with the existing posts
    currentPage++;
    
    // Check if we have more posts to show
    const filteredPosts = filterPosts(currentPosts);
    const totalPages = Math.ceil(filteredPosts.length / POSTS_PER_PAGE);
    
    if (currentPage > totalPages) {
      hasMorePosts = false;
    } else {
      // Render the grid with the updated page
      renderGrid(false); // Don't reset the grid
    }
  } catch (error) {
    console.error('Error loading more posts:', error);
  } finally {
    isLoading = false;
    hideLoadingIndicator();
  }
}

/**
 * Renders the post grid with current posts and filters
 * @param {boolean} resetGrid - Whether to reset the grid before rendering
 */
function renderGrid(resetGrid = true) {
  const gridContainer = document.getElementById('post-grid');
  if (!gridContainer) return;
  
  // Apply filters to the current posts
  const filteredPosts = filterPosts(currentPosts);
  
  // Calculate pagination
  const startIndex = 0;
  const endIndex = currentPage * POSTS_PER_PAGE;
  const postsToShow = filteredPosts.slice(startIndex, endIndex);
  
  // Check if we have more posts
  hasMorePosts = endIndex < filteredPosts.length;
  
  // Reset grid if needed
  if (resetGrid) {
    gridContainer.innerHTML = '';
    gridContainer.className = 'masonry-grid';
  }
  
  // Create and append post cards
  postsToShow.forEach(post => {
    // Skip if this post is already in the grid
    if (!resetGrid && gridContainer.querySelector(`[data-id="${post.id}"]`)) {
      return;
    }
    
    const card = createPostCard(
      post,
      (tag) => handleTagClick(tag),
      (postId) => handlePostDelete(postId)
    );
    
    if (card) {
      gridContainer.appendChild(card);
    }
  });
  
  // Show empty state if no posts
  if (postsToShow.length === 0 && resetGrid) {
    const emptyState = document.createElement('div');
    emptyState.className = 'col-span-full p-8 text-center text-gray-500';
    
    if (activeFilters.tags.length > 0 || activeFilters.platform || activeFilters.search) {
      emptyState.textContent = 'No posts match your filters. Try adjusting your criteria.';
    } else {
      emptyState.textContent = 'No posts yet. Add your first link using the button above.';
    }
    
    gridContainer.appendChild(emptyState);
  }
  
  // Initialize any embedded content
  initializeEmbeds();
}

/**
 * Filters posts based on active filters
 * @param {Array} posts - Posts to filter
 * @returns {Array} Filtered posts
 */
function filterPosts(posts) {
  return posts.filter(post => {
    // Filter by tags
    if (activeFilters.tags.length > 0) {
      if (!post.tags || !post.tags.some(tag => activeFilters.tags.includes(tag))) {
        return false;
      }
    }
    
    // Filter by platform
    if (activeFilters.platform && post.platform !== activeFilters.platform) {
      return false;
    }
    
    // Filter by search
    if (activeFilters.search) {
      const searchLower = activeFilters.search.toLowerCase();
      const titleMatch = post.title && post.title.toLowerCase().includes(searchLower);
      const descriptionMatch = post.description && post.description.toLowerCase().includes(searchLower);
      const urlMatch = post.url && post.url.toLowerCase().includes(searchLower);
      
      if (!titleMatch && !descriptionMatch && !urlMatch) {
        return false;
      }
    }
    
    return true;
  });
}

/**
 * Handles tag click event
 * @param {string} tag - The clicked tag
 */
function handleTagClick(tag) {
  // Toggle tag in filters
  if (activeFilters.tags.includes(tag)) {
    activeFilters.tags = activeFilters.tags.filter(t => t !== tag);
  } else {
    activeFilters.tags = [...activeFilters.tags, tag];
  }
  
  // Reset pagination
  currentPage = 1;
  hasMorePosts = true;
  
  // Render the grid with the updated filters
  renderGrid();
  
  // Dispatch event to update tag UI
  window.dispatchEvent(new CustomEvent('filter:tag:updated', {
    detail: { tags: activeFilters.tags }
  }));
}

/**
 * Handles post deletion
 * @param {string} postId - ID of the deleted post
 */
function handlePostDelete(postId) {
  // Remove post from current posts
  currentPosts = currentPosts.filter(post => post.id !== postId);
  
  // Remove post card from the DOM
  const card = document.querySelector(`[data-id="${postId}"]`);
  if (card) {
    card.remove();
  }
  
  // Check if we need to load more posts
  if (currentPosts.length === 0) {
    hasMorePosts = false;
    renderGrid();
  }
}

/**
 * Shows the loading indicator
 */
function showLoadingIndicator() {
  const indicator = document.getElementById('loading-indicator');
  if (indicator) {
    indicator.classList.remove('hidden');
  }
}

/**
 * Hides the loading indicator
 */
function hideLoadingIndicator() {
  const indicator = document.getElementById('loading-indicator');
  if (indicator) {
    indicator.classList.add('hidden');
  }
}

/**
 * Initializes embedded content (Twitter, Instagram, etc.)
 */
function initializeEmbeds() {
  // Initialize Twitter embeds
  if (window.twttr && window.twttr.widgets) {
    window.twttr.widgets.load();
  }
  
  // Initialize Instagram embeds
  if (window.instgrm && window.instgrm.Embeds) {
    window.instgrm.Embeds.process();
  }
}
