// simple-auth.js - Simplified authentication functionality
import { supabase } from './utils/supabaseClient.js';

// Track current auth state
let currentUser = null;

// Wait for DOM to be ready
document.addEventListener('DOMContentLoaded', () => {
  console.log('Simple Auth: DOM loaded');
  // We'll initialize from main.js instead to ensure proper order
});

function initSimpleAuth() {
  console.log('Simple Auth: Initializing');
  
  try {
    // Set up auth state listener first
    setupAuthStateListener();
    
    // Look for auth button with multiple possible IDs
    let authButton = document.getElementById('auth-button') || 
                    document.getElementById('loginBtn');
                    
    console.log('Auth button found:', !!authButton);
    
    if (!authButton) {
      const authContainer = document.getElementById('auth-container') || 
                           document.getElementById('userSection');
      
      if (authContainer) {
        console.log('Auth container found, creating button');
        authButton = document.createElement('button');
        authButton.id = 'auth-button';
        authButton.textContent = 'Sign In';
        authButton.className = 'text-primary hover:text-blue-700 font-medium';
        authButton.style.padding = '8px 16px';
        authButton.style.backgroundColor = '#4f46e5';
        authButton.style.color = 'white';
        authButton.style.border = 'none';
        authButton.style.borderRadius = '4px';
        authButton.style.cursor = 'pointer';
        authContainer.appendChild(authButton);
        console.log('Simple Auth: Created auth button');
      } else {
        console.warn('Simple Auth: No auth container found');
      }
    }
  
  // Get the existing auth modal from HTML
  const authModal = document.getElementById('auth-modal');
  
  if (!authModal) {
    console.log('Simple Auth: Creating auth modal');
    // Create modal if it doesn't exist
    const modalDiv = document.createElement('div');
    modalDiv.id = 'auth-modal';
    modalDiv.className = 'fixed inset-0 z-50 hidden';
    modalDiv.innerHTML = `
      <div class="absolute inset-0 bg-black bg-opacity-50"></div>
      <div class="relative top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-full max-w-md bg-white dark:bg-gray-800 rounded-lg shadow-xl">
        <div class="p-6" id="auth-modal-content"></div>
      </div>
    `;
    document.body.appendChild(modalDiv);
    console.log('Simple Auth: Created auth modal');
  }
  
  const authModalContent = document.getElementById('auth-modal-content');
  
  if (authModal && authModalContent) {
    console.log('Simple Auth: Found auth modal and content');
    
    // Fill the modal content
    authModalContent.innerHTML = `
      <div class="flex border-b border-gray-200 mb-4">
        <div id="signin-tab" class="px-4 py-2 cursor-pointer border-b-2 border-indigo-600 text-indigo-600">Sign In</div>
        <div id="signup-tab" class="px-4 py-2 cursor-pointer">Sign Up</div>
        <div id="close-modal" class="ml-auto cursor-pointer">×</div>
      </div>

      <form id="signin-form" class="space-y-4">
        <div>
          <label for="signin-email" class="block mb-1 font-medium">Email</label>
          <input type="email" id="signin-email" required class="w-full px-3 py-2 border border-gray-300 rounded-md">
        </div>
        <div>
          <label for="signin-password" class="block mb-1 font-medium">Password</label>
          <input type="password" id="signin-password" required class="w-full px-3 py-2 border border-gray-300 rounded-md">
        </div>
        <button type="submit" class="w-full py-2 px-4 bg-indigo-600 text-white rounded-md hover:bg-indigo-700">Sign In</button>
      </form>

      <form id="signup-form" class="hidden space-y-4">
        <div>
          <label for="signup-email" class="block mb-1 font-medium">Email</label>
          <input type="email" id="signup-email" required class="w-full px-3 py-2 border border-gray-300 rounded-md">
        </div>
        <div>
          <label for="signup-password" class="block mb-1 font-medium">Password</label>
          <input type="password" id="signup-password" required class="w-full px-3 py-2 border border-gray-300 rounded-md">
        </div>
        <button type="submit" class="w-full py-2 px-4 bg-indigo-600 text-white rounded-md hover:bg-indigo-700">Sign Up</button>
      </form>
    `;
    
    console.log('Simple Auth: Updated auth modal content');
  } else {
    console.error('Simple Auth: Could not find auth modal or content element in HTML');
  }
  
  // Setup event listeners for auth button and modal
  setupAuthListeners();
  } catch (error) {
    console.error('Error in initSimpleAuth:', error);
  }
}

function setupAuthListeners() {
  console.log('Simple Auth: Setting up listeners');
  
  // Auth button click - look for multiple possible button IDs
  const authButton = document.getElementById('auth-button') || 
                    document.getElementById('loginBtn');
  const authModal = document.getElementById('auth-modal');
  
  if (authButton && authModal) {
    console.log('Simple Auth: Found auth button and modal for click handler');
    authButton.onclick = function() {
      console.log('Simple Auth: Auth button clicked');
      console.log('Auth modal element:', authModal);
      
      // Use both classList and style.display for maximum compatibility
      authModal.classList.remove('hidden');
      authModal.style.display = 'block';
      
      // Log the modal state after showing it
      setTimeout(() => {
        console.log('Modal display after click:', 
          window.getComputedStyle(authModal).display,
          'classList:', authModal.classList);
      }, 50);
      
      // Force browser to recognize style change
      void authModal.offsetWidth;
    };
      
      // Log modal state for debugging
      console.log('Modal classList:', authModal.classList);
      console.log('Modal computed style:', window.getComputedStyle(authModal).display);
    };
    
    // Close modal
    const closeModal = document.getElementById('close-modal');
    if (closeModal) {
      closeModal.onclick = function() {
        // Use classList instead of style
        authModal.classList.add('hidden');
      };
    }
    
    // Tab switching
    const signinTab = document.getElementById('signin-tab');
    const signupTab = document.getElementById('signup-tab');
    const signinForm = document.getElementById('signin-form');
    const signupForm = document.getElementById('signup-form');
    
    if (signinTab && signupTab && signinForm && signupForm) {
      signinTab.onclick = function() {
        // Use classList for Tailwind compatibility
        signinTab.classList.add('border-b-2', 'border-indigo-600', 'text-indigo-600');
        signupTab.classList.remove('border-b-2', 'border-indigo-600', 'text-indigo-600');
        signinForm.classList.remove('hidden');
        signupForm.classList.add('hidden');
      };
      
      signupTab.onclick = function() {
        signinTab.classList.remove('border-b-2', 'border-indigo-600', 'text-indigo-600');
        signupTab.classList.add('border-b-2', 'border-indigo-600', 'text-indigo-600');
        signinForm.classList.add('hidden');
        signupForm.classList.remove('hidden');
      };
    }
    
    // Form submission
    if (signinForm) {
      signinForm.onsubmit = async function(e) {
        e.preventDefault();
        
        const email = document.getElementById('signin-email').value;
        const password = document.getElementById('signin-password').value;
        
        console.log('Simple Auth: Attempting sign in with', email);
        
        try {
          const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
          });
          
          if (error) {
            console.error('Simple Auth: Sign in error', error);
            alert('Sign in error: ' + error.message);
          } else {
            console.log('Simple Auth: Sign in successful', data);
            authModal.style.display = 'none';
            alert('Signed in successfully!');
            window.location.reload();
          }
        } catch (err) {
          console.error('Simple Auth: Exception during sign in', err);
          alert('Error during sign in: ' + err.message);
        }
      };
    }
    
    if (signupForm) {
      signupForm.onsubmit = async function(e) {
        e.preventDefault();
        
        const email = document.getElementById('signup-email').value;
        const password = document.getElementById('signup-password').value;
        
        console.log('Simple Auth: Attempting sign up with', email);
        
        try {
          const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
              data: {
                email_confirmed: true
              }
            }
          });
          
          if (error) {
            console.error('Simple Auth: Sign up error', error);
            alert('Sign up error: ' + error.message);
          } else {
            console.log('Simple Auth: Sign up successful', data);
            
            // For development, try to sign in right away
            if (!data.session) {
              alert('Account created. You can now sign in.');
              signinTab.click();
              document.getElementById('signin-email').value = email;
              document.getElementById('signin-password').value = password;
            } else {
              authModal.style.display = 'none';
              alert('Signed up and logged in successfully!');
              window.location.reload();
            }
          }
        } catch (err) {
          console.error('Simple Auth: Exception during sign up', err);
          alert('Error during sign up: ' + err.message);
        }
      };
    }
  }

// Handle auth state changes
function setupAuthStateListener() {
  console.log('Simple Auth: Setting up auth state listener');
  
  // Check current session
  supabase.auth.getSession().then(({ data }) => {
    if (data.session) {
      currentUser = data.session.user;
      updateAuthUI(true);
      console.log('Simple Auth: User already logged in', currentUser.email);
    } else {
      currentUser = null;
      updateAuthUI(false);
      console.log('Simple Auth: No active session');
    }
  });
  
  // Listen for auth changes
  supabase.auth.onAuthStateChange((event, session) => {
    console.log('Simple Auth: Auth state changed', event);
    
    if (event === 'SIGNED_IN' && session) {
      currentUser = session.user;
      updateAuthUI(true);
      console.log('Simple Auth: User signed in', currentUser.email);
      
      // Dispatch event that other components can listen for
      window.dispatchEvent(new CustomEvent('user:signed-in', { 
        detail: { userId: currentUser.id }
      }));
    } else if (event === 'SIGNED_OUT') {
      currentUser = null;
      updateAuthUI(false);
      console.log('Simple Auth: User signed out');
      
      // Dispatch event that other components can listen for
      window.dispatchEvent(new CustomEvent('user:signed-out'));
    }
  });
}

// Update UI based on auth state
function updateAuthUI(isAuthenticated) {
  const authButton = document.getElementById('auth-button');
  
  if (authButton) {
    if (isAuthenticated) {
      authButton.textContent = 'Sign Out';
      document.body.classList.add('user-logged-in');
      
      // Change button action to sign out
      authButton.onclick = async function() {
        console.log('Simple Auth: Sign out requested');
        try {
          const { error } = await supabase.auth.signOut();
          if (error) {
            console.error('Simple Auth: Sign out error', error);
            alert('Error signing out: ' + error.message);
          }
        } catch (err) {
          console.error('Simple Auth: Exception during sign out', err);
        }
      };
    } else {
      authButton.textContent = 'Sign In';
      document.body.classList.remove('user-logged-in');
      
      // Restore button action to show modal
      const authModal = document.getElementById('auth-modal');
      if (authModal) {
        authButton.onclick = function() {
          console.log('Simple Auth: Showing auth modal');
          // Use classList for Tailwind compatibility
          authModal.classList.remove('hidden');
          
          // Log modal state for debugging
          console.log('Modal classList:', authModal.classList);
          console.log('Modal computed style:', window.getComputedStyle(authModal).display);
        };
      } else {
        console.error('Simple Auth: Auth modal not found when setting up click handler');
      }
    }
  }
}

// Export functions for direct access
export { initSimpleAuth, currentUser };
