// PostCard.js - Component for rendering individual post cards
import { removePost, updatePost } from '../utils/api.js';
import { showConfirm, showToast, formatDate } from '../utils/dom.js';
import { getCurrentUser } from '../utils/supabaseClient.js';

/**
 * Creates a post card element
 * @param {Object} post - Post data
 * @param {Function} onTagClick - Callback for tag click
 * @param {Function} onDelete - Callback for post deletion
 * @returns {HTMLElement} The post card element
 */
export function createPostCard(post, onTagClick, onDelete) {
  if (!post) return null;
  
  // Create card container
  const card = document.createElement('div');
  card.className = 'post-card mb-4 break-inside-avoid';
  card.dataset.id = post.id;
  card.dataset.platform = post.platform;
  
  // Create card header
  const header = document.createElement('div');
  header.className = 'p-4 border-b border-gray-100';
  
  // Create title
  const title = document.createElement('h3');
  title.className = 'font-bold text-lg mb-1 text-gray-900';
  title.textContent = post.title || post.url;
  
  // Create description if available
  let description = null;
  if (post.description) {
    description = document.createElement('p');
    description.className = 'text-gray-600 text-sm mb-2';
    description.textContent = post.description;
  }
  
  // Create metadata (platform, date)
  const metadata = document.createElement('div');
  metadata.className = 'flex items-center text-xs text-gray-500 mb-2';
  
  const platformBadge = document.createElement('span');
  platformBadge.className = 'bg-gray-100 rounded px-2 py-1 mr-2 capitalize';
  platformBadge.textContent = post.platform || 'website';
  
  const dateSpan = document.createElement('span');
  dateSpan.textContent = formatDate(post.created_at);
  
  metadata.appendChild(platformBadge);
  metadata.appendChild(dateSpan);
  
  // Create tags container
  const tagsContainer = document.createElement('div');
  tagsContainer.className = 'flex flex-wrap gap-2 mt-2';
  
  // Add tags if available
  if (post.tags && post.tags.length > 0) {
    post.tags.forEach(tag => {
      const tagElement = document.createElement('span');
      tagElement.className = 'tag';
      tagElement.textContent = tag;
      tagElement.addEventListener('click', () => {
        if (onTagClick) onTagClick(tag);
      });
      tagsContainer.appendChild(tagElement);
    });
  }
  
  // Append elements to header
  header.appendChild(title);
  if (description) header.appendChild(description);
  header.appendChild(metadata);
  header.appendChild(tagsContainer);
  
  // Create card content
  const content = document.createElement('div');
  content.className = 'p-0';
  
  // Set embed HTML
  if (post.embed_html) {
    content.innerHTML = post.embed_html;
  } else {
    // Fallback for posts without embed HTML
    const fallback = document.createElement('div');
    fallback.className = 'p-4 text-center text-gray-500';
    
    const link = document.createElement('a');
    link.href = post.url;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.className = 'text-primary-600 hover:underline';
    link.textContent = 'Open link';
    
    fallback.appendChild(link);
    content.appendChild(fallback);
  }
  
  // Create card footer with actions
  const footer = document.createElement('div');
  footer.className = 'p-3 bg-gray-50 border-t border-gray-100 flex justify-between items-center';
  
  // Create action buttons container
  const actions = document.createElement('div');
  actions.className = 'flex space-x-2';
  
  // Create edit tags button
  const editTagsBtn = document.createElement('button');
  editTagsBtn.className = 'text-xs text-gray-600 hover:text-primary-600';
  editTagsBtn.textContent = 'Edit Tags';
  editTagsBtn.addEventListener('click', () => handleEditTags(post));
  
  // Create delete button
  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'text-xs text-red-600 hover:text-red-800';
  deleteBtn.textContent = 'Delete';
  deleteBtn.addEventListener('click', async () => {
    showConfirm('Are you sure you want to delete this post?', async () => {
      try {
        const user = await getCurrentUser();
        const userId = user ? user.id : null;
        
        await removePost(post.id, userId);
        
        // Call onDelete callback
        if (onDelete) onDelete(post.id);
        
        // Show success message
        showToast('Post deleted successfully', 'success');
      } catch (error) {
        console.error('Error deleting post:', error);
        showToast('Error deleting post', 'error');
      }
    });
  });
  
  // Create open link button
  const openLinkBtn = document.createElement('a');
  openLinkBtn.href = post.url;
  openLinkBtn.target = '_blank';
  openLinkBtn.rel = 'noopener noreferrer';
  openLinkBtn.className = 'text-xs text-primary-600 hover:text-primary-800';
  openLinkBtn.textContent = 'Open Link';
  
  // Add buttons to actions
  actions.appendChild(editTagsBtn);
  actions.appendChild(deleteBtn);
  
  // Add open link to footer
  footer.appendChild(actions);
  footer.appendChild(openLinkBtn);
  
  // Assemble card
  card.appendChild(header);
  card.appendChild(content);
  card.appendChild(footer);
  
  return card;
}

/**
 * Handles editing tags for a post
 * @param {Object} post - The post to edit tags for
 */
async function handleEditTags(post) {
  // Create a modal for editing tags
  const modal = document.createElement('div');
  modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50';
  
  const modalContent = document.createElement('div');
  modalContent.className = 'bg-white p-6 rounded-lg shadow-lg max-w-md w-full';
  
  const heading = document.createElement('h3');
  heading.className = 'text-lg font-bold mb-4';
  heading.textContent = 'Edit Tags';
  
  const form = document.createElement('form');
  form.className = 'space-y-4';
  
  const inputLabel = document.createElement('label');
  inputLabel.htmlFor = 'edit-tags-input';
  inputLabel.className = 'form-label';
  inputLabel.textContent = 'Tags (comma separated)';
  
  const input = document.createElement('input');
  input.type = 'text';
  input.id = 'edit-tags-input';
  input.className = 'form-input';
  input.value = post.tags ? post.tags.join(', ') : '';
  
  const buttonContainer = document.createElement('div');
  buttonContainer.className = 'flex justify-end space-x-2';
  
  const cancelButton = document.createElement('button');
  cancelButton.type = 'button';
  cancelButton.className = 'btn btn-secondary';
  cancelButton.textContent = 'Cancel';
  cancelButton.addEventListener('click', () => {
    document.body.removeChild(modal);
  });
  
  const saveButton = document.createElement('button');
  saveButton.type = 'submit';
  saveButton.className = 'btn btn-primary';
  saveButton.textContent = 'Save';
  
  buttonContainer.appendChild(cancelButton);
  buttonContainer.appendChild(saveButton);
  
  form.appendChild(inputLabel);
  form.appendChild(input);
  form.appendChild(buttonContainer);
  
  modalContent.appendChild(heading);
  modalContent.appendChild(form);
  
  modal.appendChild(modalContent);
  
  // Add form submit handler
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    
    try {
      saveButton.disabled = true;
      saveButton.textContent = 'Saving...';
      
      // Parse tags
      const tagsString = input.value.trim();
      const tags = tagsString
        ? tagsString.split(',').map(tag => tag.trim()).filter(tag => tag)
        : [];
      
      // Get current user
      const user = await getCurrentUser();
      const userId = user ? user.id : null;
      
      // Update post with new tags
      const updatedPost = {
        ...post,
        tags
      };
      
      await updatePost(post.id, updatedPost, userId);
      
      // Show success message
      showToast('Tags updated successfully', 'success');
      
      // Dispatch event to notify other components
      window.dispatchEvent(new CustomEvent('post:updated', { 
        detail: { 
          postId: post.id,
          updates: { tags }
        } 
      }));
      
      // Close modal
      document.body.removeChild(modal);
    } catch (error) {
      console.error('Error updating tags:', error);
      showToast('Error updating tags', 'error');
      
      // Reset button state
      saveButton.disabled = false;
      saveButton.textContent = 'Save';
    }
  });
  
  // Add modal to document
  document.body.appendChild(modal);
  
  // Focus input
  input.focus();
}
