// main.js - Application entry point
import './main.css';
import { initApp } from './app.js';
import { initServiceWorker } from './utils/serviceWorker.js';
import { initDebug, checkDomElements, checkStyles } from './debug.js';
// Import the simplified auth module
import { initSimpleAuth } from './simple-auth.js';

// Log deployment information
console.log('Boardie App - GitHub Pages Deployment');
console.log('Base URL:', import.meta.env.BASE_URL);
console.log('Environment:', import.meta.env.MODE);

// Initialize the application when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', () => {
  console.log('DOM fully loaded');
  
  // Add a timeout to ensure all elements are fully rendered
  setTimeout(() => {
    try {
      // Initialize debugging tools
      initDebug();
      console.log('Debug initialized');
      
      // Initialize the service worker for PWA functionality
      initServiceWorker();
      console.log('Service worker initialized');
      
      // Initialize the simplified auth system first with retry logic
      let authInitialized = false;
      const initAuthWithRetry = (attempts = 0) => {
        try {
          console.log(`Attempting to initialize auth (attempt ${attempts + 1})`);
          initSimpleAuth();
          console.log('Auth system initialized');
          authInitialized = true;
        } catch (authError) {
          console.error('Auth initialization error:', authError);
          if (attempts < 3) {
            console.log(`Retrying auth initialization in ${(attempts + 1) * 500}ms...`);
            setTimeout(() => initAuthWithRetry(attempts + 1), (attempts + 1) * 500);
          } else {
            console.error('Failed to initialize auth after multiple attempts');
          }
        }
      };
      
      initAuthWithRetry();
      
      // Initialize the main application
      initApp().then(() => {
        console.log('App initialized successfully');
        
        // Check DOM elements and styles
        checkDomElements();
        checkStyles();
        
        // Handle shared content from Share Target API
        handleSharedContent();
        
        // Log success message
        console.log('Boardie application is ready!');
      }).catch(error => {
        console.error('Error initializing app:', error);
      });
    } catch (error) {
      console.error('Critical initialization error:', error);
    }
  }, 300); // Small delay to ensure DOM is fully processed
});

/**
 * Handles content shared via the Web Share Target API
 * This function checks URL parameters for shared content and processes it
 */
function handleSharedContent() {
  const urlParams = new URLSearchParams(window.location.search);
  const sharedUrl = urlParams.get('url');
  const sharedTitle = urlParams.get('title');
  const sharedText = urlParams.get('text');
  
  // If there's a shared URL, extract it and process it
  if (sharedUrl || (sharedText && sharedText.includes('http'))) {
    const url = sharedUrl || extractUrlFromText(sharedText);
    
    if (url) {
      // Clear URL parameters without reloading the page
      window.history.replaceState({}, document.title, window.location.pathname);
      
      // Show the add link form with the shared URL pre-filled
      const addLinkBtn = document.getElementById('add-link-btn');
      if (addLinkBtn) {
        addLinkBtn.click();
        
        // Short delay to ensure the form is visible before setting values
        setTimeout(() => {
          const urlInput = document.getElementById('link-url');
          const titleInput = document.getElementById('link-title');
          
          if (urlInput) urlInput.value = url;
          if (titleInput && sharedTitle) titleInput.value = sharedTitle;
        }, 100);
      }
    }
  }
}

/**
 * Extracts a URL from text content
 * @param {string} text - Text that might contain a URL
 * @returns {string|null} - Extracted URL or null if none found
 */
function extractUrlFromText(text) {
  if (!text) return null;
  
  // Simple regex to extract URLs from text
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  const matches = text.match(urlRegex);
  
  return matches && matches.length > 0 ? matches[0] : null;
}
