// api.js - API functions for fetching and updating posts
import { supabase } from './supabaseClient.js';
import { savePost, getPosts as getLocalPosts, deletePost } from './storage.js';

/**
 * Fetches all posts for a specific user from Supabase
 * @param {string} userId - The user ID
 * @returns {Promise<Array>} Array of posts
 */
export async function getUserPosts(userId) {
  if (!userId) {
    console.error('User ID is required to fetch posts');
    return [];
  }
  
  try {
    const { data, error } = await supabase
      .from('posts')
      .select('*')
      .eq('user_id', userId)
      .order('position', { ascending: true });
    
    if (error) {
      console.error('Error fetching user posts:', error);
      return [];
    }
    
    return data || [];
  } catch (error) {
    console.error('Error fetching user posts:', error);
    return [];
  }
}

/**
 * Creates a new post in Supabase and local storage
 * @param {Object} postData - Post data to create
 * @param {string} userId - User ID (optional for unauthenticated users)
 * @returns {Promise<Object>} Created post
 */
export async function createPost(postData, userId) {
  try {
    // Validate required fields
    if (!postData.url) {
      throw new Error('URL is required for creating a post');
    }

    // Add a temporary local ID for immediate UI update
    const tempId = `local_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
    
    // Ensure tags is an array
    const tags = Array.isArray(postData.tags) ? postData.tags : 
                (postData.tags ? [postData.tags] : []);
    
    // Create local post object with proper formatting
    let post = { 
      ...postData,
      id: tempId, 
      user_id: userId,
      tags: tags, // Ensure tags is an array
      url: postData.url.trim(), // Ensure URL is trimmed
      created_at: new Date().toISOString(), 
      updated_at: new Date().toISOString() 
    };

    // 1. Save locally first (using IndexedDB function)
    await savePost(post);

    // 2. If online and authenticated, attempt to save to Supabase
    if (navigator.onLine && userId) {
      console.log('Attempting to save post to Supabase');
      
      // Prepare data for Supabase with correct formatting
      const postToSaveSupabase = {
        url: post.url, // Required field
        title: post.title || '', // Optional fields with defaults
        description: post.description || '',
        platform: post.platform || 'website',
        embed_html: post.embed_html || '',
        tags: tags, // Ensure tags is properly formatted as an array
        position: post.position || 0,
        user_id: userId // Required field
      };
      
      // Log the exact data being sent to Supabase for debugging
      console.log('Sending to Supabase:', postToSaveSupabase);

      const { data, error } = await supabase
        .from('posts')
        .insert([postToSaveSupabase])
        .select()
        .single()

      if (error) {
        console.error('Error creating post in Supabase:', error);
        // Keep the local version, background sync might handle it later
        // Optionally: notify user of sync issue
      } else if (data) {
        console.log('Post saved to Supabase, updating local store:', data);
        // 3. Update the locally saved post with the ID and timestamps from Supabase
        // First, remove the old temporary local post
        await deletePost(tempId); // Use deletePost (imported from storage.js)
        // Then, save the confirmed data from Supabase
        await savePost(data); // savePost should handle adding the new record
        post = data; // Update the post variable to return the Supabase version
      }
    } else if (!userId) {
       console.log('User not authenticated, post saved locally only:', post.id);
    } else if (!navigator.onLine) {
       console.log('App offline, post saved locally only:', post.id);
    }

    return post; // Return the locally saved post (potentially updated with Supabase ID)

  } catch (error) {
    console.error('Error in createPost function:', error);
    // Depending on requirements, you might want to remove the local post
    // if the entire process fails catastrophically.
    // await deletePostFromDB(tempId); // Example cleanup
    throw error; // Re-throw the error to be handled by the caller
  }
}

/**
 * Fetches posts from Supabase and caches them locally.
 * Filters by user ID if provided.
 * @param {string} userId - Optional user ID to filter posts
 * @returns {Promise<Array<Object>>} Array of posts
 */
export async function getPosts(userId) {
  let posts = [];
  try {
    // 1. Try fetching from Supabase if online
    if (navigator.onLine) {
      console.log(`Fetching posts from Supabase for user: ${userId || 'all'}`);
      let query = supabase.from('posts').select('*').order('created_at', { ascending: false });
      if (userId) {
        query = query.eq('user_id', userId); // Filter by user_id
      }
      const { data, error } = await query;

      if (error) {
        console.error('Error fetching posts from Supabase:', error);
        // Fallback to local cache if Supabase fetch fails
        posts = await getLocalPosts();
      } else {
        console.log('Fetched posts from Supabase:', data.length);
        posts = data;
        // 2. Update local cache with fetched data
        for (const post of posts) {
          await savePost(post); // Save fresh data locally
        }
      }
    } else {
      // 3. If offline, fetch directly from local cache
      console.log('Offline, fetching posts from local DB');
      posts = await getLocalPosts();
    }
  } catch (error) {
    console.error('Error fetching posts:', error);
    // Attempt to load from local cache as a last resort
    try {
      posts = await getLocalPosts();
    } catch (dbError) {
      console.error('Error fetching posts from local DB:', dbError);
      posts = []; // Return empty array if both fail
    }
  }
    // Ensure posts are filtered by user if userId is provided, especially for offline data
    if (userId) {
      // Make sure the post objects actually have the user_id field for filtering
      return posts.filter(post => post && post.user_id === userId);
    }
    return posts;

}

/**
 * Updates an existing post in Supabase and local storage
 * @param {Object} postData - Updated post data (must include id)
 * @returns {Promise<Object>} Updated post
 */
export async function updatePost(postData) {
  if (!postData.id) {
    console.error("Update failed: Post data must include an ID.");
    throw new Error("Post ID is required for updates.");
  }

  // Ensure timestamps are updated
  postData.updated_at = new Date().toISOString();

  try {
    // 1. Update locally first
    await savePost(postData); // savePost should handle updates if ID exists

    // 2. If online, attempt to update in Supabase
    if (navigator.onLine) {
       const { data: { user } } = await supabase.auth.getUser(); // Get current user
       // RLS might depend on the user matching the post's user_id
       if (!user && postData.user_id) {
         console.warn("Attempting to update post without being logged in or user_id mismatch. This might fail due to RLS.");
       } else if (user && postData.user_id !== user.id) {
         console.warn("Attempting to update a post belonging to a different user. This might fail due to RLS.");
         // Decide if you should prevent this or let Supabase RLS handle it
       }

      console.log('Attempting to update post in Supabase:', postData.id);
       // Prepare data for Supabase - remove local-only fields if necessary
       const updateData = { ...postData };
       // Ensure user_id is included if needed for RLS or if it can be changed.
       // Supabase handles updated_at automatically if configured correctly.
       // delete updateData.id; // Don't try to update the primary key itself
       const idToUpdate = updateData.id;
       delete updateData.id; // Remove id from the data payload for update
       // Avoid sending created_at for updates unless necessary
       // delete updateData.created_at;

      const { data, error } = await supabase
        .from('posts')
        .update(updateData)
        .eq('id', idToUpdate) // Match the specific post using the stored ID
        .select()
        .single();

      if (error) {
        console.error('Error updating post in Supabase:', error);
        // Local version is already updated. Sync might handle later.
        // Optionally notify user.
      } else if (data) {
        console.log('Post updated in Supabase, updating local store:', data);
        // 3. Re-save the definitive data from Supabase locally
        await savePost(data);
        return data;
      }
    } else {
        console.log('Offline, post updated locally only:', postData.id);
    }

    return postData; // Return the locally updated post data

  } catch (error) {
    console.error('Error updating post:', error);
    throw error;
  }
}

/**
 * Deletes a post from Supabase and local storage
 * @param {string} postId - ID of the post to delete
 * @param {string} userId - User ID (optional)
 * @returns {Promise<boolean>} Success indicator
 */
export async function removePost(postId, userId = null) {
   if (!postId) {
    console.error("Delete failed: Post ID is required.");
    throw new Error("Post ID is required for deletion.");
  }
  try {
    // 1. Delete locally first
    const localSuccess = await deletePost(postId, userId); // Use deletePost (imported from storage.js)
    if (!localSuccess) {
      console.error('Failed to delete post from local storage');
      return false;
    }

    // 2. If online and authenticated, attempt to delete from Supabase
    if (navigator.onLine && userId) {
      console.log('Attempting to delete post from Supabase:', postId);
      const { error } = await supabase
        .from('posts')
        .delete()
        .match({ id: postId, user_id: userId }); // Match both ID and user_id for RLS

      if (error) {
        console.error('Error deleting post from Supabase:', error);
        // Local version is already deleted, but Supabase deletion failed
        // This is a partial success - we'll return true since the local delete worked
        console.warn('Post deleted locally but not from Supabase');
      } else {
        console.log('Post deleted from Supabase:', postId);
      }
    } else if (!navigator.onLine) {
      console.log('Offline, post deleted locally only:', postId);
      // When back online, sync process should handle the deletion
    } else if (!userId) {
      console.log('User not authenticated, post deleted locally only:', postId);
    }

    return true; // Return success if we got this far
  } catch (error) {
    console.error('Error deleting post:', error);
    return false; // Return failure on error
  }
}

/**
 * Extracts platform type from URL
 * @param {string} url - URL to analyze
 * @returns {string} Platform type (twitter, instagram, youtube, linkedin, website)
 */
export function getPlatformFromUrl(url) {
  if (!url) return 'website';
  
  const lowerUrl = url.toLowerCase();
  
  if (lowerUrl.includes('twitter.com') || lowerUrl.includes('x.com')) {
    return 'twitter';
  } else if (lowerUrl.includes('instagram.com')) {
    return 'instagram';
  } else if (lowerUrl.includes('youtube.com') || lowerUrl.includes('youtu.be')) {
    return 'youtube';
  } else if (lowerUrl.includes('linkedin.com')) {
    return 'linkedin';
  } else {
    return 'website';
  }
}

/**
 * Generates embed HTML based on the platform and URL
 * @param {string} url - The post URL
 * @param {string} platform - The platform type
 * @returns {Promise<string>} HTML for embedding
 */
export async function generateEmbedHtml(url, platform) {
  switch (platform) {
    case 'twitter':
      return generateTwitterEmbed(url);
    case 'instagram':
      return generateInstagramEmbed(url);
    case 'youtube':
      return generateYoutubeEmbed(url);
    case 'linkedin':
      return generateLinkedinEmbed(url);
    case 'website':
    default:
      return generateWebsiteEmbed(url);
  }
}

/**
 * Generates Twitter embed HTML
 * @param {string} url - Twitter post URL
 * @returns {string} HTML for embedding
 */
function generateTwitterEmbed(url) {
  // Extract tweet ID if possible
  let tweetId = '';
  const match = url.match(/twitter\.com\/\w+\/status\/(\d+)/);
  if (match) {
    tweetId = match[1];
  } else {
    // Alternative match for x.com
    const xMatch = url.match(/x\.com\/\w+\/status\/(\d+)/);
    if (xMatch) {
      tweetId = xMatch[1];
    }
  }
  
  if (tweetId) {
    return `<blockquote class="twitter-tweet" data-dnt="true">
              <a href="${url}"></a>
            </blockquote>
            <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script>`;
  } else {
    return generateWebsiteEmbed(url);
  }
}

/**
 * Generates Instagram embed HTML
 * @param {string} url - Instagram post URL
 * @returns {string} HTML for embedding
 */
function generateInstagramEmbed(url) {
  return `<blockquote class="instagram-media" data-instgrm-permalink="${url}" 
            data-instgrm-version="14" style="width: 100%; max-width: 540px;">
            <a href="${url}"></a>
          </blockquote>
          <script async src="//www.instagram.com/embed.js"></script>`;
}

/**
 * Generates YouTube embed HTML
 * @param {string} url - YouTube video URL
 * @returns {string} HTML for embedding
 */
function generateYoutubeEmbed(url) {
  // Extract video ID
  let videoId = '';
  
  // Handle youtu.be format
  if (url.includes('youtu.be/')) {
    const match = url.match(/youtu\.be\/([^?&]+)/);
    if (match) {
      videoId = match[1];
    }
  } 
  // Handle youtube.com format
  else {
    const match = url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/);
    if (match) {
      videoId = match[1];
    }
  }
  
  if (videoId) {
    return `<div class="youtube-container">
              <iframe width="560" height="315" 
                src="https://www.youtube.com/embed/${videoId}" 
                frameborder="0" 
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                allowfullscreen>
              </iframe>
            </div>`;
  } else {
    return generateWebsiteEmbed(url);
  }
}

