/**
 * Generates generic website embed HTML
 * @param {string} url - Website URL
 * @returns {string} HTML for embedding
 */
function generateWebsiteEmbed(url) {
  return `<div class="website-card">
            <a href="${url}" target="_blank" rel="noopener noreferrer" class="website-link">
              <div class="website-preview">
                <div class="website-thumbnail" data-url="${url}"></div>
                <div class="website-content">
                  <div class="website-title" data-url="${url}">Loading...</div>
                  <div class="website-description" data-url="${url}"></div>
                  <div class="website-url">${url}</div>
                </div>
              </div>
            </a>
          </div>`;
}

