// storage.js - Offline storage utilities (IndexedDB with localStorage fallback)
import { openDB } from 'idb';
import { supabase } from './supabaseClient.js';

// Database name and version
const DB_NAME = 'boardieDB';
const DB_VERSION = 1;

// Store names
const POSTS_STORE = 'posts';
const SYNC_STORE = 'syncQueue';

let db = null;
let usingFallback = false;

/**
 * Initialize the local storage (IndexedDB or localStorage fallback)
 * @returns {Promise<void>}
 */
export async function initLocalStorage() {
  try {
    // Try to initialize IndexedDB
    db = await openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        // Create posts object store
        if (!db.objectStoreNames.contains(POSTS_STORE)) {
          const postsStore = db.createObjectStore(POSTS_STORE, { keyPath: 'id' });
          postsStore.createIndex('userId', 'userId', { unique: false });
          postsStore.createIndex('platform', 'platform', { unique: false });
          postsStore.createIndex('tags', 'tags', { unique: false, multiEntry: true });
        }
        
        // Create sync queue object store
        if (!db.objectStoreNames.contains(SYNC_STORE)) {
          const syncStore = db.createObjectStore(SYNC_STORE, { 
            keyPath: 'id',
            autoIncrement: true 
          });
          syncStore.createIndex('operation', 'operation', { unique: false });
          syncStore.createIndex('userId', 'userId', { unique: false });
        }
      }
    });
    
    console.log('IndexedDB initialized successfully');
    usingFallback = false;
  } catch (error) {
    console.warn('Error initializing IndexedDB, falling back to localStorage:', error);
    usingFallback = true;
    
    // Initialize localStorage if needed
    if (!localStorage.getItem(POSTS_STORE)) {
      localStorage.setItem(POSTS_STORE, JSON.stringify([]));
    }
    
    if (!localStorage.getItem(SYNC_STORE)) {
      localStorage.setItem(SYNC_STORE, JSON.stringify([]));
    }
  }
}

/**
 * Saves a post to local storage
 * @param {Object} post - The post to save
 * @returns {Promise<string>} The ID of the saved post
 */
export async function savePost(post) {
  // Generate UUID if not provided
  if (!post.id) {
    post.id = generateUUID();
  }
  
  // Set timestamps
  const now = new Date().toISOString();
  if (!post.created_at) {
    post.created_at = now;
  }
  post.updated_at = now;
  
  try {
    if (!usingFallback) {
      // Save to IndexedDB
      await db.put(POSTS_STORE, post);
    } else {
      // Save to localStorage
      const posts = JSON.parse(localStorage.getItem(POSTS_STORE) || '[]');
      const existingIndex = posts.findIndex(p => p.id === post.id);
      
      if (existingIndex >= 0) {
        posts[existingIndex] = post;
      } else {
        posts.push(post);
      }
      
      localStorage.setItem(POSTS_STORE, JSON.stringify(posts));
    }
    
    // Add to sync queue if user is logged in
    if (post.userId) {
      await addToSyncQueue({
        operation: 'upsert',
        userId: post.userId,
        entityType: 'post',
        entityId: post.id,
        data: post
      });
    }
    
    return post.id;
  } catch (error) {
    console.error('Error saving post to local storage:', error);
    throw error;
  }
}

/**
 * Gets all posts from local storage for a specific user
 * @param {string} userId - The user ID (optional, for authenticated users)
 * @returns {Promise<Array>} Array of posts
 */
export async function getPosts(userId = null) {
  try {
    if (!usingFallback) {
      // Get from IndexedDB
      if (userId) {
        return await db.getAllFromIndex(POSTS_STORE, 'userId', userId);
      } else {
        return await db.getAll(POSTS_STORE);
      }
    } else {
      // Get from localStorage
      const posts = JSON.parse(localStorage.getItem(POSTS_STORE) || '[]');
      
      if (userId) {
        return posts.filter(post => post.userId === userId);
      } else {
        return posts;
      }
    }
  } catch (error) {
    console.error('Error getting posts from local storage:', error);
    return [];
  }
}

/**
 * Gets a specific post by ID
 * @param {string} postId - The post ID
 * @returns {Promise<Object|null>} The post or null if not found
 */
export async function getPost(postId) {
  try {
    if (!usingFallback) {
      // Get from IndexedDB
      return await db.get(POSTS_STORE, postId);
    } else {
      // Get from localStorage
      const posts = JSON.parse(localStorage.getItem(POSTS_STORE) || '[]');
      return posts.find(post => post.id === postId) || null;
    }
  } catch (error) {
    console.error('Error getting post from local storage:', error);
    return null;
  }
}

/**
 * Deletes a post from local storage
 * @param {string} postId - The post ID
 * @param {string} userId - The user ID (optional, for authenticated users)
 * @returns {Promise<boolean>} Success indicator
 */
export async function deletePost(postId, userId = null) {
  try {
    // Get the post first to check if it exists
    const post = await getPost(postId);
    
    if (!post) {
      return false;
    }
    
    if (!usingFallback) {
      // Delete from IndexedDB
      await db.delete(POSTS_STORE, postId);
    } else {
      // Delete from localStorage
      const posts = JSON.parse(localStorage.getItem(POSTS_STORE) || '[]');
      const newPosts = posts.filter(post => post.id !== postId);
      localStorage.setItem(POSTS_STORE, JSON.stringify(newPosts));
    }
    
    // Add to sync queue if user is logged in
    if (userId) {
      await addToSyncQueue({
        operation: 'delete',
        userId,
        entityType: 'post',
        entityId: postId
      });
    }
    
    return true;
  } catch (error) {
    console.error('Error deleting post from local storage:', error);
    return false;
  }
}

/**
 * Adds an operation to the sync queue for later synchronization
 * @param {Object} operation - The operation details
 * @returns {Promise<void>}
 */
async function addToSyncQueue(operation) {
  try {
    if (!usingFallback) {
      // Add to IndexedDB
      await db.add(SYNC_STORE, operation);
    } else {
      // Add to localStorage
      const syncQueue = JSON.parse(localStorage.getItem(SYNC_STORE) || '[]');
      operation.id = syncQueue.length + 1; // Simple auto-increment
      syncQueue.push(operation);
      localStorage.setItem(SYNC_STORE, JSON.stringify(syncQueue));
    }
  } catch (error) {
    console.error('Error adding to sync queue:', error);
  }
}

/**
 * Synchronize local data with Supabase when online
 * @param {string} userId - The user ID
 * @returns {Promise<void>}
 */
export async function syncWithSupabase(userId) {
  if (!navigator.onLine || !userId) {
    return;
  }
  
  try {
    // Get operations from sync queue for this user
    let operations = [];
    
    if (!usingFallback) {
      // Get from IndexedDB
      const tx = db.transaction(SYNC_STORE, 'readwrite');
      const index = tx.store.index('userId');
      operations = await index.getAll(userId);
      
      // Clear processed operations
      for (const op of operations) {
        await tx.store.delete(op.id);
      }
      
      await tx.done;
    } else {
      // Get from localStorage
      const syncQueue = JSON.parse(localStorage.getItem(SYNC_STORE) || '[]');
      operations = syncQueue.filter(op => op.userId === userId);
      
      // Clear processed operations
      const newSyncQueue = syncQueue.filter(op => op.userId !== userId);
      localStorage.setItem(SYNC_STORE, JSON.stringify(newSyncQueue));
    }
    
    // Process operations
    for (const operation of operations) {
      await processOperation(operation);
    }
    
    // After sync, pull down latest data from Supabase
    await pullFromSupabase(userId);
  } catch (error) {
    console.error('Error syncing with Supabase:', error);
  }
}

/**
 * Process a single operation against Supabase
 * @param {Object} operation - The operation to process
 * @returns {Promise<void>}
 */
async function processOperation(operation) {
  const { operation: type, entityType, entityId, data } = operation;
  
  if (entityType === 'post') {
    if (type === 'upsert') {
      // Update or insert post
      const { error } = await supabase
        .from('posts')
        .upsert(data, { onConflict: 'id' });
      
      if (error) {
        console.error('Error upserting post to Supabase:', error);
      }
    } else if (type === 'delete') {
      // Delete post
      const { error } = await supabase
        .from('posts')
        .delete()
        .match({ id: entityId });
      
      if (error) {
        console.error('Error deleting post from Supabase:', error);
      }
    }
  }
}

/**
 * Pull the latest data from Supabase to local storage
 * @param {string} userId - The user ID
 * @returns {Promise<void>}
 */
async function pullFromSupabase(userId) {
  try {
    // Get all posts for this user from Supabase
    const { data: posts, error } = await supabase
      .from('posts')
      .select('*')
      .eq('user_id', userId);
    
    if (error) {
      console.error('Error getting posts from Supabase:', error);
      return;
    }
    
    // Update local storage with the latest data
    if (!usingFallback) {
      // Update IndexedDB
      const tx = db.transaction(POSTS_STORE, 'readwrite');
      
      // Clear existing posts for this user
      const userIndex = tx.store.index('userId');
      const existingPosts = await userIndex.getAll(userId);
      for (const post of existingPosts) {
        await tx.store.delete(post.id);
      }
      
      // Add new posts
      for (const post of posts) {
        await tx.store.put(post);
      }
      
      await tx.done;
    } else {
      // Update localStorage
      const allPosts = JSON.parse(localStorage.getItem(POSTS_STORE) || '[]');
      
      // Remove existing posts for this user
      const filteredPosts = allPosts.filter(post => post.userId !== userId);
      
      // Add new posts
      const newPosts = [...filteredPosts, ...posts];
      localStorage.setItem(POSTS_STORE, JSON.stringify(newPosts));
    }
  } catch (error) {
    console.error('Error pulling data from Supabase:', error);
  }
}

/**
 * Generate a UUID v4 (random)
 * @returns {string} A UUID v4 string
 */
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
