// debug.js - Helper script for debugging application issues
console.log('Debug script loaded');

// Export a function to check DOM elements
export function checkDomElements() {
  console.log('Checking DOM elements...');
  
  const elements = {
    addLinkBtn: document.getElementById('add-link-btn'),
    postGrid: document.getElementById('post-grid'),
    tagList: document.getElementById('tag-list'),
    authContainer: document.getElementById('auth-container'),
    authModal: document.getElementById('auth-modal'),
    authModalContent: document.getElementById('auth-modal-content')
  };
  
  console.table(
    Object.entries(elements).map(([name, element]) => ({
      name,
      exists: !!element,
      classes: element ? element.className : 'N/A'
    }))
  );
  
  return elements;
}

// Export a function to check styles
export function checkStyles() {
  console.log('Checking if styles are loaded...');
  
  // Check if Tailwind classes are applied
  const header = document.querySelector('header');
  const computedStyle = header ? window.getComputedStyle(header) : null;
  
  console.log('Header element:', header);
  console.log('Header computed style:', computedStyle ? {
    position: computedStyle.position,
    backgroundColor: computedStyle.backgroundColor,
    boxShadow: computedStyle.boxShadow
  } : 'N/A');
  
  return !!computedStyle;
}

// Export a function to check Supabase connection
export async function checkSupabaseConnection() {
  console.log('Checking Supabase connection...');
  
  try {
    // Try to import supabase client
    const { supabase } = await import('./utils/supabaseClient.js');
    
    // Check if we can connect to Supabase
    const { data, error } = await supabase.from('posts').select('count', { count: 'exact', head: true });
    
    if (error) {
      console.error('Supabase connection error:', error);
      return false;
    }
    
    console.log('Supabase connection successful');
    return true;
  } catch (error) {
    console.error('Error checking Supabase connection:', error);
    return false;
  }
}

// Export a function to fix auth button
export function fixAuthButton() {
  console.log('Fixing auth button...');
  
  const authContainer = document.getElementById('auth-container');
  if (!authContainer) {
    console.error('Auth container not found');
    return false;
  }
  
  // Create auth button if it doesn't exist
  let authButton = document.getElementById('auth-button');
  if (!authButton) {
    authButton = document.createElement('button');
    authButton.id = 'auth-button';
    authButton.className = 'text-gray-600 hover:text-primary-600';
    authButton.textContent = 'Sign In';
    authContainer.appendChild(authButton);
  }
  
  // Add click handler to toggle auth modal
  authButton.onclick = function() {
    const authModal = document.getElementById('auth-modal');
    if (authModal) {
      authModal.classList.toggle('hidden');
    }
  };
  
  console.log('Auth button fixed');
  return true;
}

// Export a debug init function
export function initDebug() {
  console.log('Initializing debug tools...');
  
  // Add debug info to window for console access
  window.boardieDebug = {
    checkDomElements,
    checkStyles,
    checkSupabaseConnection,
    fixAuthButton
  };
  
  console.log('Debug tools initialized. Access via window.boardieDebug in console');
}
