// app.js - App initialization and orchestration
import { initSupabase, supabase } from './utils/supabaseClient.js';
import { initLocalStorage, syncWithSupabase } from './utils/storage.js';
import { initAddLink } from './components/AddLink.js';
import { initPostGrid } from './components/PostGrid.js';
import { initTagManager } from './components/TagManager.js';
import { getUserPosts } from './utils/api.js';

let isInitialized = false;
let currentUser = null;

/**
 * Initializes the application
 * Sets up event listeners, components, and data connections
 * @returns {Promise} Promise that resolves when initialization is complete
 */
export async function initApp() {
  if (isInitialized) return Promise.resolve();
  
  // Initialize Supabase client
  initSupabase();
  
  // Initialize local storage
  await initLocalStorage();
  
  // Initialize UI components
  initAddLink();
  initPostGrid();
  initTagManager();
  
  // Set up auth state change listener
  supabase.auth.onAuthStateChange((event, session) => {
    if (event === 'SIGNED_IN' && session) {
      currentUser = session.user;
      handleUserSignIn(currentUser);
    } else if (event === 'SIGNED_OUT') {
      currentUser = null;
      handleUserSignOut();
    }
  });
  
  // Check for existing session
  const { data: { session } } = await supabase.auth.getSession();
  if (session) {
    currentUser = session.user;
    handleUserSignIn(currentUser);
  } else {
    // If no user is logged in, show local posts if available
    loadLocalPosts();
  }
  
  // Set up UI event listeners
  setupEventListeners();
  
  isInitialized = true;
  
  return Promise.resolve();
}

/**
 * Handles user sign in event
 * @param {Object} user - The signed in user object
 */
async function handleUserSignIn(user) {
  if (!user) return;
  
  // Update UI to reflect logged in state
  document.body.classList.add('user-logged-in');
  
  // Sync local data with Supabase
  await syncWithSupabase(user.id);
  
  // Load user's posts from Supabase
  await loadUserPosts(user.id);
  
  // Dispatch event to notify components about user login
  window.dispatchEvent(new CustomEvent('user:signed-in', { detail: { userId: user.id } }));
}

/**
 * Handles user sign out event
 */
function handleUserSignOut() {
  // Update UI to reflect logged out state
  document.body.classList.remove('user-logged-in');
  
  // Load local posts if available
  loadLocalPosts();
  
  // Dispatch event to notify components about user logout
  window.dispatchEvent(new CustomEvent('user:signed-out'));
}

/**
 * Loads user's posts from Supabase
 * @param {string} userId - User ID to load posts for
 */
async function loadUserPosts(userId) {
  if (!userId) return;
  
  // Show loading indicator
  const loadingIndicator = document.getElementById('loading-indicator');
  if (loadingIndicator) loadingIndicator.classList.remove('hidden');
  
  try {
    // Fetch posts from Supabase
    const posts = await getUserPosts(userId);
    
    // Update the post grid with fetched posts
    window.dispatchEvent(new CustomEvent('posts:loaded', { detail: { posts } }));
  } catch (error) {
    console.error('Error loading user posts:', error);
  } finally {
    // Hide loading indicator
    if (loadingIndicator) loadingIndicator.classList.add('hidden');
  }
}

/**
 * Loads posts from local storage when not signed in
 */
function loadLocalPosts() {
  // Dispatch event to load posts from local storage
  window.dispatchEvent(new CustomEvent('posts:load-local'));
}

/**
 * Sets up global event listeners for the application
 */
function setupEventListeners() {
  // Add link button click handler
  const addLinkBtn = document.getElementById('add-link-btn');
  if (addLinkBtn) {
    addLinkBtn.addEventListener('click', toggleAddLinkForm);
  }
  
  // Listen for network status changes
  window.addEventListener('online', handleOnline);
  window.addEventListener('offline', handleOffline);
  
  // Initial network status check
  if (navigator.onLine) {
    handleOnline();
  } else {
    handleOffline();
  }
}

/**
 * Toggles the visibility of the add link form
 */
function toggleAddLinkForm() {
  const formContainer = document.getElementById('add-link-form-container');
  if (formContainer) {
    formContainer.classList.toggle('hidden');
    
    // Focus on URL input when form is shown
    if (!formContainer.classList.contains('hidden')) {
      const urlInput = document.getElementById('link-url');
      if (urlInput) {
        urlInput.focus();
      }
    }
  }
}

/**
 * Handles when the app comes online
 */
function handleOnline() {
  document.body.classList.remove('offline-mode');
  document.body.classList.add('online-mode');
  
  // If user is logged in, sync data with Supabase
  if (currentUser) {
    syncWithSupabase(currentUser.id);
  }
  
  // Notify components about online status
  window.dispatchEvent(new CustomEvent('network:online'));
}

/**
 * Handles when the app goes offline
 */
function handleOffline() {
  document.body.classList.remove('online-mode');
  document.body.classList.add('offline-mode');
  
  // Notify components about offline status
  window.dispatchEvent(new CustomEvent('network:offline'));
}
